INSERT INTO verses (translation_id, book_id, chapter, verse, text, words_of_jesus) VALUES
('ylt','GEN',1,1,'In the beginning of God''s preparing the heavens and the earth —',NULL),
('ylt','GEN',1,2,'the earth hath existed waste and void, and darkness [is] on the face of the deep, and the Spirit of God fluttering on the face of the waters,',NULL),
('ylt','GEN',1,3,'and God saith, ''Let light be;'' and light is.',NULL),
('ylt','GEN',1,4,'And God seeth the light that [it is] good, and God separateth between the light and the darkness,',NULL),
('ylt','GEN',1,5,'and God calleth to the light ''Day,'' and to the darkness He hath called ''Night;'' and there is an evening, and there is a morning — day one.',NULL),
('ylt','GEN',1,6,'And God saith, ''Let an expanse be in the midst of the waters, and let it be separating between waters and waters.''',NULL),
('ylt','GEN',1,7,'And God maketh the expanse, and it separateth between the waters which [are] under the expanse, and the waters which [are] above the expanse: and it is so.',NULL),
('ylt','GEN',1,8,'And God calleth to the expanse ''Heavens;'' and there is an evening, and there is a morning — day second.',NULL),
('ylt','GEN',1,9,'And God saith, ''Let the waters under the heavens be collected unto one place, and let the dry land be seen:'' and it is so.',NULL),
('ylt','GEN',1,10,'And God calleth to the dry land ''Earth,'' and to the collection of the waters He hath called ''Seas;'' and God seeth that [it is] good.',NULL),
('ylt','GEN',1,11,'And God saith, ''Let the earth yield tender grass, herb sowing seed, fruit-tree (whose seed [is] in itself) making fruit after its kind, on the earth:'' and it is so.',NULL),
('ylt','GEN',1,12,'And the earth bringeth forth tender grass, herb sowing seed after its kind, and tree making fruit (whose seed [is] in itself) after its kind; and God seeth that [it is] good;',NULL),
('ylt','GEN',1,13,'and there is an evening, and there is a morning — day third.',NULL),
('ylt','GEN',1,14,'And God saith, ''Let luminaries be in the expanse of the heavens, to make a separation between the day and the night, then they have been for signs, and for seasons, and for days and years,',NULL),
('ylt','GEN',1,15,'and they have been for luminaries in the expanse of the heavens to give light upon the earth:'' and it is so.',NULL),
('ylt','GEN',1,16,'And God maketh the two great luminaries, the great luminary for the rule of the day, and the small luminary — and the stars — for the rule of the night;',NULL),
('ylt','GEN',1,17,'and God giveth them in the expanse of the heavens to give light upon the earth,',NULL),
('ylt','GEN',1,18,'and to rule over day and over night, and to make a separation between the light and the darkness; and God seeth that [it is] good;',NULL),
('ylt','GEN',1,19,'and there is an evening, and there is a morning — day fourth.',NULL),
('ylt','GEN',1,20,'And God saith, ''Let the waters teem with the teeming living creature, and fowl let fly on the earth on the face of the expanse of the heavens.''',NULL),
('ylt','GEN',1,21,'And God prepareth the great monsters, and every living creature that is creeping, which the waters have teemed with, after their kind, and every fowl with wing, after its kind, and God seeth that [it is] good.',NULL),
('ylt','GEN',1,22,'And God blesseth them, saying, ''Be fruitful, and multiply, and fill the waters in the seas, and the fowl let multiply in the earth:''',NULL),
('ylt','GEN',1,23,'and there is an evening, and there is a morning — day fifth.',NULL),
('ylt','GEN',1,24,'And God saith, ''Let the earth bring forth the living creature after its kind, cattle and creeping thing, and beast of the earth after its kind:'' and it is so.',NULL),
('ylt','GEN',1,25,'And God maketh the beast of the earth after its kind, and the cattle after their kind, and every creeping thing of the ground after its kind, and God seeth that [it is] good.',NULL),
('ylt','GEN',1,26,'And God saith, ''Let Us make man in Our image, according to Our likeness, and let them rule over fish of the sea, and over fowl of the heavens, and over cattle, and over all the earth, and over every creeping thing that is creeping on the earth.''',NULL),
('ylt','GEN',1,27,'And God prepareth the man in His image; in the image of God He prepared him, a male and a female He prepared them.',NULL),
('ylt','GEN',1,28,'And God blesseth them, and God saith to them, ''Be fruitful, and multiply, and fill the earth, and subdue it, and rule over fish of the sea, and over fowl of the heavens, and over every living thing that is creeping upon the earth.''',NULL),
('ylt','GEN',1,29,'And God saith, ''Lo, I have given to you every herb sowing seed, which [is] upon the face of all the earth, and every tree in which [is] the fruit of a tree sowing seed, to you it is for food;',NULL),
('ylt','GEN',1,30,'and to every beast of the earth, and to every fowl of the heavens, and to every creeping thing on the earth, in which [is] breath of life, every green herb [is] for food:'' and it is so.',NULL),
('ylt','GEN',1,31,'And God seeth all that He hath done, and lo, very good; and there is an evening, and there is a morning — day the sixth.',NULL),
('ylt','PSA',23,1,'A Psalm of David. Jehovah [is] my shepherd, I do not lack,',NULL),
('ylt','PSA',23,2,'In pastures of tender grass He causeth me to lie down, By quiet waters He doth lead me.',NULL),
('ylt','PSA',23,3,'My soul He refresheth, He leadeth me in paths of righteousness, For His name''s sake,',NULL),
('ylt','PSA',23,4,'Also — when I walk in a valley of death-shade, I fear no evil, for Thou [art] with me, Thy rod and Thy staff — they comfort me.',NULL),
('ylt','PSA',23,5,'Thou arrangest before me a table, Over-against my adversaries, Thou hast anointed with oil my head, My cup is full!',NULL),
('ylt','PSA',23,6,'Only — goodness and kindness pursue me, All the days of my life, And my dwelling [is] in the house of Jehovah, For a length of days!',NULL),
('ylt','PSA',117,1,'Praise Jehovah, all ye nations, Glorify Him, all ye peoples.',NULL),
('ylt','PSA',117,2,'For mighty to us hath been His kindness, And the truth of Jehovah [is] to the age. Praise ye Jah!',NULL),
('ylt','MAT',11,1,'And it came to pass, when Jesus ended directing his twelve disciples, he departed thence to teach and to preach in their cities.',NULL),
('ylt','MAT',11,2,'And John having heard in the prison the works of the Christ, having sent two of his disciples,',NULL),
('ylt','MAT',11,3,'said to him, ''Art thou He who is coming, or for another do we look?''',NULL),
('ylt','MAT',11,4,'And Jesus answering said to them, ''Having gone, declare to John the things that ye hear and see,',NULL),
('ylt','MAT',11,5,'blind receive sight, and lame walk, lepers are cleansed, and deaf hear, dead are raised, and poor have good news proclaimed,',NULL),
('ylt','MAT',11,6,'and happy is he who may not be stumbled in me.''',NULL),
('ylt','MAT',11,7,'And as they are going, Jesus began to say to the multitudes concerning John, ''What went ye out to the wilderness to view? — a reed shaken by the wind?',NULL),
('ylt','MAT',11,8,'''But what went ye out to see? — a man clothed in soft garments? lo, those wearing the soft things are in the kings'' houses.',NULL),
('ylt','MAT',11,9,'''But what went ye out to see? — a prophet? yes, I say to you, and more than a prophet,',NULL),
('ylt','MAT',11,10,'for this is he of whom it hath been written, Lo, I do send My messenger before thy face, who shall prepare thy way before thee.',NULL),
('ylt','MAT',11,11,'Verily I say to you, there hath not risen, among those born of women, a greater than John the Baptist, but he who is least in the reign of the heavens is greater than he.',NULL),
('ylt','MAT',11,12,'''And, from the days of John the Baptist till now, the reign of the heavens doth suffer violence, and violent men do take it by force,',NULL),
('ylt','MAT',11,13,'for all the prophets and the law till John did prophesy,',NULL),
('ylt','MAT',11,14,'and if ye are willing to receive [it], he is Elijah who was about to come;',NULL),
('ylt','MAT',11,15,'he who is having ears to hear — let him hear.',NULL),
('ylt','MAT',11,16,'''And to what shall I liken this generation? it is like little children in market-places, sitting and calling to their comrades,',NULL),
('ylt','MAT',11,17,'and saying, We piped unto you, and ye did not dance, we lamented to you, and ye did not smite the breast.',NULL),
('ylt','MAT',11,18,'''For John came neither eating nor drinking, and they say, He hath a demon;',NULL),
('ylt','MAT',11,19,'the Son of Man came eating and drinking, and they say, Lo, a man, a glutton, and a wine-drinker, a friend of tax-gatherers and sinners, and wisdom was justified of her children.''',NULL),
('ylt','MAT',11,20,'Then began he to reproach the cities in which were done most of his mighty works, because they did not reform.',NULL),
('ylt','MAT',11,21,'''Woe to thee, Chorazin! woe to thee, Bethsaida! because, if in Tyre and Sidon had been done the mighty works that were done in you, long ago in sackcloth and ashes they had reformed;',NULL),
('ylt','MAT',11,22,'but I say to you, to Tyre and Sidon it shall be more tolerable in a day of judgment than for you.',NULL),
('ylt','MAT',11,23,'''And thou, Capernaum, which unto the heaven wast exalted, unto hades shalt be brought down, because if in Sodom had been done the mighty works that were done in thee, it had remained unto this day;',NULL),
('ylt','MAT',11,24,'but I say to you, to the land of Sodom it shall be more tolerable in a day of judgment than to thee.''',NULL),
('ylt','MAT',11,25,'At that time Jesus answering said, ''I do confess to Thee, Father, Lord of the heavens and of the earth, that thou didst hide these things from wise and understanding ones, and didst reveal them to babes.',NULL),
('ylt','MAT',11,26,'Yes, Father, because so it was good pleasure before Thee.',NULL),
('ylt','MAT',11,27,'''All things were delivered to me by my Father, and none doth know the Son, except the Father, nor doth any know the Father, except the Son, and he to whom the Son may wish to reveal [Him].',NULL),
('ylt','MAT',11,28,'''Come unto me, all ye labouring and burdened ones, and I will give you rest,',NULL),
('ylt','MAT',11,29,'take up my yoke upon you, and learn from me, because I am meek and humble in heart, and ye shall find rest to your souls,',NULL),
('ylt','MAT',11,30,'for my yoke [is] easy, and my burden is light.''',NULL),
('ylt','MAT',17,1,'And after six days Jesus taketh Peter, and James, and John his brother, and doth bring them up to a high mount by themselves,',NULL),
('ylt','MAT',17,2,'and he was transfigured before them, and his face shone as the sun, and his garments did become white as the light,',NULL),
('ylt','MAT',17,3,'and lo, appear to them did Moses and Elijah, talking together with him.',NULL),
('ylt','MAT',17,4,'And Peter answering said to Jesus, ''Sir, it is good to us to be here; if thou wilt, we may make here three booths — for thee one, and for Moses one, and one for Elijah.''',NULL),
('ylt','MAT',17,5,'While he is yet speaking, lo, a bright cloud overshadowed them, and lo, a voice out of the cloud, saying, ''This is My Son, — the Beloved, in whom I did delight; hear him.''',NULL),
('ylt','MAT',17,6,'And the disciples having heard, did fall upon their face, and were exceedingly afraid,',NULL),
('ylt','MAT',17,7,'and Jesus having come near, touched them, and said, ''Rise, be not afraid,''',NULL),
('ylt','MAT',17,8,'and having lifted up their eyes, they saw no one, except Jesus only.',NULL),
('ylt','MAT',17,9,'And as they are coming down from the mount, Jesus charged them, saying, ''Say to no one the vision, till the Son of Man out of the dead may rise.''',NULL),
('ylt','MAT',17,10,'And his disciples questioned him, saying, ''Why then do the scribes say that Elijah it behoveth to come first?''',NULL),
('ylt','MAT',17,11,'And Jesus answering said to them, ''Elijah doth indeed come first, and shall restore all things,',NULL),
('ylt','MAT',17,12,'and I say to you — Elijah did already come, and they did not know him, but did with him whatever they would, so also the Son of Man is about to suffer by them.''',NULL),
('ylt','MAT',17,13,'Then understood the disciples that concerning John the Baptist he spake to them.',NULL),
('ylt','MAT',17,14,'And when they came unto the multitude, there came to him a man, kneeling down to him,',NULL),
('ylt','MAT',17,15,'and saying, ''Sir, deal kindly with my son, for he is lunatic, and doth suffer miserably, for often he doth fall into the fire, and often into the water,',NULL),
('ylt','MAT',17,16,'and I brought him near to thy disciples, and they were not able to heal him.''',NULL),
('ylt','MAT',17,17,'And Jesus answering said, ''O generation, unstedfast and perverse, till when shall I be with you? till when shall I bear you? bring him to me hither;''',NULL),
('ylt','MAT',17,18,'and Jesus rebuked him, and the demon went out of him, and the lad was healed from that hour.',NULL),
('ylt','MAT',17,19,'Then the disciples having come to Jesus by himself, said, ''Wherefore were we not able to cast him out?''',NULL),
('ylt','MAT',17,20,'And Jesus said to them, ''Through your want of faith; for verily I say to you, if ye may have faith as a grain of mustard, ye shall say to this mount, Remove hence to yonder place, and it shall remove, and nothing shall be impossible to you,',NULL),
('ylt','MAT',17,21,'and this kind doth not go forth except in prayer and fasting.''',NULL),
('ylt','MAT',17,22,'And while they are living in Galilee, Jesus said to them, ''The Son of Man is about to be delivered up to the hands of men,',NULL),
('ylt','MAT',17,23,'and they shall kill him, and the third day he shall rise,'' and they were exceeding sorry.',NULL),
('ylt','MAT',17,24,'And they having come to Capernaum, those receiving the didrachms came near to Peter, and said, ''Your teacher — doth he not pay the didrachms?'' He saith, ''Yes.''',NULL),
('ylt','MAT',17,25,'And when he came into the house, Jesus anticipated him, saying, ''What thinkest thou, Simon? the kings of the earth — from whom do they receive custom or poll-tax? from their sons or from the strangers?''',NULL),
('ylt','MAT',17,26,'Peter saith to him, ''From the strangers.'' Jesus said to him, ''Then are the sons free;',NULL),
('ylt','MAT',17,27,'but, that we may not cause them to stumble, having gone to the sea, cast a hook, and the fish that hath come up first take thou up, and having opened its mouth, thou shalt find a stater, that having taken, give to them for me and thee.''',NULL),
('ylt','JHN',3,1,'And there was a man of the Pharisees, Nicodemus his name, a ruler of the Jews,',NULL),
('ylt','JHN',3,2,'this one came unto him by night, and said to him, ''Rabbi, we have known that from God thou hast come — a teacher, for no one these signs is able to do that thou dost, if God may not be with him.''',NULL),
('ylt','JHN',3,3,'Jesus answered and said to him, ''Verily, verily, I say to thee, If any one may not be born from above, he is not able to see the reign of God;''',NULL),
('ylt','JHN',3,4,'Nicodemus saith unto him, ''How is a man able to be born, being old? is he able into the womb of his mother a second time to enter, and to be born?''',NULL),
('ylt','JHN',3,5,'Jesus answered, ''Verily, verily, I say to thee, If any one may not be born of water, and the Spirit, he is not able to enter into the reign of God;',NULL),
('ylt','JHN',3,6,'that which hath been born of the flesh is flesh, and that which hath been born of the Spirit is spirit.',NULL),
('ylt','JHN',3,7,'''Thou mayest not wonder that I said to thee, It behoveth you to be born from above;',NULL),
('ylt','JHN',3,8,'the Spirit where he willeth doth blow, and his voice thou dost hear, but thou hast not known whence he cometh, and whither he goeth; thus is every one who hath been born of the Spirit.''',NULL),
('ylt','JHN',3,9,'Nicodemus answered and said to him, ''How are these things able to happen?''',NULL),
('ylt','JHN',3,10,'Jesus answered and said to him, ''Thou art the teacher of Israel — and these things thou dost not know!',NULL),
('ylt','JHN',3,11,'''Verily, verily, I say to thee — What we have known we speak, and what we have seen we testify, and our testimony ye do not receive;',NULL),
('ylt','JHN',3,12,'if the earthly things I said to you, and ye do not believe, how, if I shall say to you the heavenly things, will ye believe?',NULL),
('ylt','JHN',3,13,'and no one hath gone up to the heaven, except he who out of the heaven came down — the Son of Man who is in the heaven.',NULL),
('ylt','JHN',3,14,'''And as Moses did lift up the serpent in the wilderness, so it behoveth the Son of Man to be lifted up,',NULL),
('ylt','JHN',3,15,'that every one who is believing in him may not perish, but may have life age-during,',NULL),
('ylt','JHN',3,16,'for God did so love the world, that His Son — the only begotten — He gave, that every one who is believing in him may not perish, but may have life age-during.',NULL),
('ylt','JHN',3,17,'For God did not send His Son to the world that he may judge the world, but that the world may be saved through him;',NULL),
('ylt','JHN',3,18,'he who is believing in him is not judged, but he who is not believing hath been judged already, because he hath not believed in the name of the only begotten Son of God.',NULL),
('ylt','JHN',3,19,'''And this is the judgment, that the light hath come to the world, and men did love the darkness rather than the light, for their works were evil;',NULL),
('ylt','JHN',3,20,'for every one who is doing wicked things hateth the light, and doth not come unto the light, that his works may not be detected;',NULL),
('ylt','JHN',3,21,'but he who is doing the truth doth come to the light, that his works may be manifested, that in God they are having been wrought.''',NULL),
('ylt','JHN',3,22,'After these things came Jesus and his disciples to the land of Judea, and there he did tarry with them, and was baptizing;',NULL),
('ylt','JHN',3,23,'and John was also baptizing in Aenon, nigh to Salem, because there were many waters there, and they were coming and were being baptized —',NULL),
('ylt','JHN',3,24,'for John was not yet cast into the prison —',NULL),
('ylt','JHN',3,25,'there arose then a question from the disciples of John with [some] Jews about purifying,',NULL),
('ylt','JHN',3,26,'and they came unto John, and said to him, ''Rabbi, he who was with thee beyond the Jordan, to whom thou didst testify, lo, this one is baptizing, and all are coming unto him.''',NULL),
('ylt','JHN',3,27,'John answered and said, ''A man is not able to receive anything, if it may not have been given him from the heaven;',NULL),
('ylt','JHN',3,28,'ye yourselves do testify to me that I said, I am not the Christ, but, that I am having been sent before him;',NULL),
('ylt','JHN',3,29,'he who is having the bride is bridegroom, and the friend of the bridegroom, who is standing and hearing him, with joy doth rejoice because of the voice of the bridegroom; this, then, my joy hath been fulfilled.',NULL),
('ylt','JHN',3,30,'''Him it behoveth to increase, and me to become less;',NULL),
('ylt','JHN',3,31,'he who from above is coming is above all; he who is from the earth, from the earth he is, and from the earth he speaketh; he who from the heaven is coming is above all.',NULL),
('ylt','JHN',3,32,'''And what he hath seen and heard this he doth testify, and his testimony none receiveth;',NULL),
('ylt','JHN',3,33,'he who is receiving his testimony did seal that God is true;',NULL),
('ylt','JHN',3,34,'for he whom God sent, the sayings of God he speaketh; for not by measure doth God give the Spirit;',NULL),
('ylt','JHN',3,35,'the Father doth love the Son, and all things hath given into his hand;',NULL),
('ylt','JHN',3,36,'he who is believing in the Son, hath life age-during; and he who is not believing the Son, shall not see life, but the wrath of God doth remain upon him.''',NULL),
('ylt','3JN',1,1,'The Elder to Gaius the beloved, whom I love in truth!',NULL),
('ylt','3JN',1,2,'beloved, concerning all things I desire thee to prosper, and to be in health, even as thy soul doth prosper,',NULL),
('ylt','3JN',1,3,'for I rejoiced exceedingly, brethren coming and testifying of the truth in thee, even as thou in truth dost walk;',NULL),
('ylt','3JN',1,4,'greater than these things I have no joy, that I may hear of my children in truth walking.',NULL),
('ylt','3JN',1,5,'Beloved, faithfully dost thou do whatever thou mayest work to the brethren and to the strangers,',NULL),
('ylt','3JN',1,6,'who did testify of thy love before an assembly, whom thou wilt do well, having sent forward worthily of God,',NULL),
('ylt','3JN',1,7,'because for [His] name they went forth, nothing receiving from the nations;',NULL),
('ylt','3JN',1,8,'we, then, ought to receive such, that fellow-workers we may become to the truth.',NULL),
('ylt','3JN',1,9,'I did write to the assembly, but he who is loving the first place among them — Diotrephes — doth not receive us;',NULL),
('ylt','3JN',1,10,'because of this, if I may come, I will cause him to remember his works that he doth, with evil words prating against us; and not content with these, neither doth he himself receive the brethren, and those intending he doth forbid, and out of the assembly he doth cast.',NULL),
('ylt','3JN',1,11,'Beloved, be not thou following that which is evil, but that which is good; he who is doing good, of God he is, and he who is doing evil hath not seen God;',NULL),
('ylt','3JN',1,12,'to Demetrius testimony hath been given by all, and by the truth itself, and we also — we do testify, and ye have known that our testimony is true.',NULL),
('ylt','3JN',1,13,'Many things I had to write, but I do not wish through ink and pen to write to thee,',NULL),
('ylt','3JN',1,14,'and I hope straightway to see thee, and mouth to mouth we shall speak. Peace to thee! salute thee do the friends; be saluting the friends by name.',NULL),
('ylt','REV',12,1,'And a great sign was seen in the heaven, a woman arrayed with the sun, and the moon under her feet, and upon her head a crown of twelve stars,',NULL),
('ylt','REV',12,2,'and being with child she doth cry out, travailing and pained to bring forth.',NULL),
('ylt','REV',12,3,'And there was seen another sign in the heaven, and, lo, a great red dragon, having seven heads and ten horns, and upon his head seven diadems,',NULL),
('ylt','REV',12,4,'and his tail doth draw the third of the stars of the heaven, and he did cast them to the earth; and the dragon did stand before the woman who is about to bring forth, that when she may bring forth, her child he may devour;',NULL),
('ylt','REV',12,5,'and she brought forth a male child, who is about to rule all the nations with a rod of iron, and caught away was her child unto God and His throne,',NULL),
('ylt','REV',12,6,'and the woman did flee to the wilderness, where she hath a place made ready from God, that there they may nourish her — days a thousand, two hundred, sixty.',NULL),
('ylt','REV',12,7,'And there came war in the heaven; Michael and his messengers did war against the dragon, and the dragon did war, and his messengers,',NULL),
('ylt','REV',12,8,'and they did not prevail, nor was their place found any more in the heaven;',NULL),
('ylt','REV',12,9,'and the great dragon was cast forth — the old serpent, who is called ''Devil,'' and ''the Adversary,'' who is leading astray the whole world — he was cast forth to the earth, and his messengers were cast forth with him.',NULL),
('ylt','REV',12,10,'And I heard a great voice saying in the heaven, ''Now did come the salvation, and the power, and the reign, of our God, and the authority of His Christ, because cast down was the accuser of our brethren, who is accusing them before our God day and night;',NULL),
('ylt','REV',12,11,'and they did overcome him because of the blood of the Lamb, and because of the word of their testimony, and they did not love their life — unto death;',NULL),
('ylt','REV',12,12,'because of this be glad, ye heavens, and those in them who do tabernacle; woe to those inhabiting the land and the sea, because the Devil did go down unto you, having great wrath, having known that he hath little time.''',NULL),
('ylt','REV',12,13,'And when the dragon saw that he was cast forth to the earth, he pursued the woman who did bring forth the male,',NULL),
('ylt','REV',12,14,'and there were given to the woman two wings of the great eagle, that she may fly to the wilderness, to her place, where she is nourished a time, and times, and half a time, from the face of the serpent;',NULL),
('ylt','REV',12,15,'and the serpent did cast forth after the woman, out of his mouth, water as a river, that he may cause her to be carried away by the river,',NULL),
('ylt','REV',12,16,'and the land did help the woman, and the land did open its mouth and did swallow up the river, that the dragon did cast forth out of his mouth;',NULL),
('ylt','REV',12,17,'and the dragon was angry against the woman, and went away to make war with the rest of her seed, those keeping the commands of God, and having the testimony of Jesus Christ.',NULL);
INSERT INTO verses_fts (verses_fts) VALUES ('rebuild');
